def _make(kind: str, t, config: dict[str, Any], env: dict[str, str], sandbox: bool) -> Connector:
    if kind == "stripe":
        return StripeConnector(t)
    if kind == "jira":
        projects = config.get("projects") or [p for p in env.get("JIRA_PROJECTS", "").split(",") if p]
        return JiraConnector(t, projects)
    if kind == "posthog":
        return PostHogConnector(t, str(config.get("project_id") or env.get("POSTHOG_PROJECT_ID", "1")),
                                int(config.get("group_type_index", env.get("POSTHOG_GROUP_TYPE_INDEX", 0))))
    from .sandbox import SANDBOX_TIME_FIELD_ID
    field = SANDBOX_TIME_FIELD_ID if sandbox else (int(env["ZENDESK_TIME_SPENT_FIELD_ID"])
                                                   if env.get("ZENDESK_TIME_SPENT_FIELD_ID") else None)
    return ZendeskConnector(t, field)

    """A Transport whose 'network' is a router function. `fail_first` makes the first N requests
    answer 429 with Retry-After: 0, to exercise the retry path in tests and demos."""

    def __init__(self, router: Router, fail_first: int = 0):
        self.router = router
        self.fail_first = fail_first
        self.calls: list[tuple[str, str, dict[str, Any]]] = []

    async def request(self, method: str, url: str, *, params=None, json_body=None, headers=None) -> HttpResponse:
        u = urlparse(url)
        q: dict[str, Any] = {k: (v if len(v) > 1 else v[0]) for k, v in parse_qs(u.query).items()}
        q.update(params or {})
        self.calls.append((method, u.path, q))
        if self.fail_first > 0:
            self.fail_first -= 1
            return HttpResponse(429, {"Retry-After": "0"}, {"error": "rate limited (sandbox)"})
        return self.router(method, u.path, q, json_body)


