        if s.get("current_period_end"):
            period_ends.append(s["current_period_end"])
    md = customer.get("metadata") or {}
    tier = max(tiers, key=lambda t: TIER_RANK.get(t, 0)) if tiers else md.get("tier") or ("starter" if mrr else "free")

