class BadStatsigSignature(ValueError):
    pass


def verify_statsig(secret: str, signature: str | None, timestamp: str | None, body: bytes,
                   now: float | None = None, tolerance: int = 300) -> None:
    if not signature or not timestamp:
        raise BadStatsigSignature("missing signature headers")
    if abs((now or time.time()) - int(timestamp) / (1000 if len(timestamp) > 11 else 1)) > tolerance:
        raise BadStatsigSignature("stale timestamp")
    expected = "v0=" + hmac.new(secret.encode(), f"v0:{timestamp}:".encode() + body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise BadStatsigSignature("signature mismatch")


def exposures_to_buckets(body: bytes) -> dict[str, list[EvalBucket]]:
    """Statsig event-webhook batch -> hourly on/off counts per gate."""
    doc = json.loads(body or b"[]")
    events = doc.get("data", []) if isinstance(doc, dict) else doc
    counts: dict[tuple[str, datetime], list[int]] = defaultdict(lambda: [0, 0])
    for e in events:
        if e.get("eventName") != "statsig::gate_exposure":
            continue
        md = e.get("metadata") or {}
        gate = md.get("gate")
        if not gate:
            continue
        ts = datetime.fromtimestamp(int(e.get("timestamp") or e.get("timeStamp") or 0) / 1000, tz=timezone.utc)
        hour = ts.replace(minute=0, second=0, microsecond=0)
        on = str(md.get("gateValue", md.get("value", "false"))).lower() == "true"
        counts[(gate, hour)][0 if on else 1] += 1
    out: dict[str, list[EvalBucket]] = defaultdict(list)
    for (gate, hour), (on, off) in sorted(counts.items()):
        out[gate].append(EvalBucket(hour, on, off))
    return dict(out)

def to_pgvector(v: list[float]) -> str:
    return "[" + ",".join(f"{x:.6f}" for x in v) + "]"


class HashingEmbedder:
    model = "hashing-v1-1536"

    def _one(self, text: str) -> list[float]:
        v = [0.0] * DIM
        ws = words(text)
        grams: dict[str, int] = {}
        for g in ws + [f"{a}_{b}" for a, b in zip(ws, ws[1:])]:
            grams[g] = grams.get(g, 0) + 1
        for g, tf in grams.items():
            h = hashlib.md5(g.encode()).digest()
            idx = int.from_bytes(h[:4], "big") % DIM
            sign = 1.0 if h[4] & 1 else -1.0
            weight = (1 + math.log(tf)) * (0.6 if "_" in g else 1.0)
            v[idx] += sign * weight
        return _normalize(v)

    async def embed(self, texts: list[str]) -> list[list[float]]:
        return [self._one(t) for t in texts]


class OpenAIEmbedder:
    def __init__(self, api_key: str, base_url: str, model: str):
        self.api_key, self.base_url, self.model = api_key, base_url.rstrip("/"), model

    async def embed(self, texts: list[str]) -> list[list[float]]:
        import httpx
        out: list[list[float]] = []
        async with httpx.AsyncClient(timeout=60) as client:
            for i in range(0, len(texts), 256):
                r = await client.post(f"{self.base_url}/embeddings",
                                      headers={"Authorization": f"Bearer {self.api_key}"},
                                      json={"model": self.model, "input": texts[i:i + 256], "dimensions": DIM})
                r.raise_for_status()
                out += [_normalize(d["embedding"]) for d in sorted(r.json()["data"], key=lambda d: d["index"])]
        return out


def default_embedder(env: dict[str, str] | None = None) -> Embedder:
    env = os.environ if env is None else env
    if env.get("LLM_API_KEY"):
        return OpenAIEmbedder(env["LLM_API_KEY"], env.get("LLM_BASE_URL", "https://api.openai.com/v1"),
                              env.get("EMBEDDING_MODEL", "text-embedding-3-small"))
    return HashingEmbedder()

"""Automatic features.yaml sync on GitHub push.

GitHub sends a `push` event; if any commit on the default branch added or modified `features.yaml` or
`.featureledger/features.yaml`, the file is fetched at the pushed commit, validated, and applied through
`manifest_store.record_and_apply`. An invalid file is recorded (with its structured errors) on the
manifest history and the GitHub integration's health; the active manifest and every mapping stay as they were.
A removed manifest is recorded as `removed` and changes nothing: deleting ownership must be deliberate.
"""
from __future__ import annotations

import base64
import os
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, Protocol

from .manifest_store import ApplyResult, record_and_apply

MANIFEST_PATHS = ("features.yaml", ".featureledger/features.yaml")


class Fetcher(Protocol):
