    ctx.db.execute("UPDATE refresh_tokens SET revoked_at = ? WHERE user_id = ? AND revoked_at IS NULL",
                   (now_iso(), user_id))
    ctx.db.execute("UPDATE users SET token_version = token_version + 1 WHERE id = ?", (user_id,))

