def slug(text: str) -> str:
    t = re.sub(r"[^\w֐-׿]+", "-", text.lower()).strip("-")
    return t[:60] or "task"


def _grams(s: str) -> set[str]:
    s = re.sub(r"\s+", " ", s.lower())
    return {s[i:i + 3] for i in range(max(0, len(s) - 2))}

    return t[:60] or "task"


