// Encrypted backup: the database is already encrypted, so the backup file is just its ciphertext.
// Restoring needs the passcode that was in use when the backup was made.
import * as cr from "./crypto.js";
import * as db from "./db.js";

const MAGIC = "DOCMIND-BACKUP-1";

function toB64(v) {
  if (v instanceof Uint8Array) return { $u8: cr.b64(v) };
  if (v instanceof ArrayBuffer) return { $u8: cr.b64(new Uint8Array(v)) };
  if (Array.isArray(v)) return v.map(toB64);
  if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, toB64(x)]));
  return v;
}
function fromB64(v) {
  if (v && typeof v === "object" && "$u8" in v) return cr.unb64(v.$u8);
  if (Array.isArray(v)) return v.map(fromB64);
  if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, fromB64(x)]));
  return v;
}

export async function exportBackup() {
  const out = { magic: MAGIC, created_at: new Date().toISOString(), stores: {} };
  for (const s of db.STORES) out.stores[s] = (await db.all(s)).filter(([k]) => !String(k).startsWith("fail_")).map(([k, v]) => [k, toB64(v)]);
  const name = `docmind-backup-${new Date().toISOString().slice(0, 10)}.docmind`;
  return new File([JSON.stringify(out)], name, { type: "application/octet-stream" });
}

export async function importBackup(file) {
  let data;
  try { data = JSON.parse(await file.text()); } catch { throw Object.assign(new Error("invalid_backup"), { code: "invalid_backup" }); }
  if (data.magic !== MAGIC || !data.stores?.kv?.some(([k]) => k === "app")) throw Object.assign(new Error("invalid_backup"), { code: "invalid_backup" });
  await db.clearAll();
  for (const [s, rows] of Object.entries(data.stores)) {
    if (!db.STORES.includes(s)) continue;
    for (const [k, v] of rows) await db.put(s, k, fromB64(v));
  }
}

// Document understanding, a port of backend/docmind/services/classifier.py. Runs on the phone.
import C from "../catalog.js";

const { DOC_TYPES, KNOWN_ISSUERS } = C;
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

export function norm(s) {
  return (s || "").toLowerCase().replace(/״/g, "\"").replace(/׳/g, "'").replace(/[”“]/g, "\"").replace(/\s+/g, " ");
}

function count(text, kw) {
  if (/^[a-z0-9' \-/<.]+$/.test(kw)) {
    const m = text.match(new RegExp("(?<![a-z])" + esc(kw) + "(?![a-z])", "g"));
    return m ? m.length : 0;
  }
  let n = 0, i = text.indexOf(kw);
  while (i >= 0) { n++; i = text.indexOf(kw, i + kw.length); }
  return n;
}

export function validIsraeliId(num) {
  if (!/^\d{1,9}$/.test(num) || /^0+$/.test(num)) return false;
  const s = num.padStart(9, "0");
  let total = 0;
  for (let i = 0; i < 9; i++) { let d = +s[i] * (1 + (i % 2)); if (d > 9) d -= 9; total += d; }
  return total % 10 === 0;
}

function structural(text) {
  const out = {};
  if (/P<ISR|P<[A-Z]{3}[A-Z<]{5,}/.test(text)) out.passport = 8;
  if (/\bIL\d{2}\s?(?:\d{4}\s?){4}\d{3}\b/.test(text)) out.bank_confirmation = 1.5;
  for (const m of text.matchAll(/(?<!\d)(\d{9})(?!\d)/g)) {
    if (validIsraeliId(m[1])) { out.id_card = (out.id_card || 0) + 1; out.id_appendix = (out.id_appendix || 0) + 0.5; break; }
  }
  return out;
}

export function scoreTypes(text, filename) {
  const t = norm(text), fn = norm(filename);
  const scores = {};
  for (const [key, spec] of Object.entries(DOC_TYPES)) {
    let s = 0;
    for (const [kw, w] of Object.entries(spec.kw)) {
      const hits = count(t, norm(kw));
      if (hits) s += w * (1 + 0.25 * Math.min(hits - 1, 4));
    }
    if (spec.fn.some((h) => fn.includes(h))) s += 3;
    if (s) scores[key] = s;
  }
  for (const [k, v] of Object.entries(structural(text))) scores[k] = (scores[k] || 0) + v;
  if ((scores.id_appendix || 0) >= 5 && scores.id_card) scores.id_card *= 0.6;
  if (scores.reserve_order && scores.reserve_service_confirmation) {
    if (["ימי מילואים", "3010", "days of reserve"].some((k) => t.includes(k))) scores.reserve_order *= 0.5;
    else if (["להתייצב", "report for duty", "צו 8"].some((k) => t.includes(k))) scores.reserve_service_confirmation *= 0.5;
  }
  return scores;
}

