  const q = query.toLowerCase().split(/\s+/).filter((w) => w.length > 1);
  for (const d of ix.docs) {
    if (scored.has(d.id) || !q.length) continue;
    const n = d.display_name.toLowerCase();
    const hits = q.filter((w) => n.includes(w)).length;
