}

export function similarity(a, b) {
  const idx = new Index([{ doc: { doc_type: "", category_key: "" }, text: a }]);
  const va = idx.vector(grams(a)), vb = idx.vector(grams(b));
  let s = 0;
  for (const [g, w] of va) { const x = vb.get(g); if (x) s += w * x; }
