    else:
        action = f"You are on the congested 2.4 GHz band{(' channel ' + str(wifi.channel)) if wifi.channel else ''}: switch to 5 GHz. "
    return text, action, (8.0 if weak else 0.0) + (3.0 if on_24 else 0.0)

