# ------------------------------------------------------------- band helpers
def band_from_frequency(mhz: float | None) -> str | None:
    if mhz is None:
        return None
    if 2400 <= mhz < 2500:
        return "2.4 GHz"
    if 4900 <= mhz < 5925:
        return "5 GHz"
    if 5925 <= mhz <= 7125:
        return "6 GHz"
    return None


def channel_from_frequency(mhz: float | None) -> int | None:
    if mhz is None:
        return None
    mhz = int(round(mhz))
    if mhz == 2484:
        return 14
    if 2412 <= mhz <= 2472:
        return (mhz - 2407) // 5
    if 5955 <= mhz <= 7115:
        return (mhz - 5950) // 5
    if 4910 <= mhz <= 5895:
        return (mhz - 5000) // 5
    return None

