            <KV k="Expected loss (keep A)" v={`${(b.expected_loss_a * 100).toFixed(4)} pp`} />
            <KV k="Uplift 95% CrI" v={`${fmtPct(b.uplift_cred_low, 1, true)} … ${fmtPct(b.uplift_cred_high, 1, true)}`} />
