  const adjP = S.holm(tests.map((t2) => t2.p));
  tests.forEach((t2, i) => (t2.p = adjP[i]!));
  const best = tests.filter((t2) => t2.r < 0).sort((a, b) => a.r - b.r)[0];
  if (best) {
