const cats = new Set<string>();
const cells: AiEvalResult["category_matrix"] = [];
for (const x of models) {
  const g = by.get(x.model)!;
  const perCat = new Map<string, { acc: number[]; hal: number }>();
  g.cat.forEach((c, i) => {
