/* FitVision AI – pose worker (classic Web Worker, section 6.1.2).
 * Runs MediaPipe Pose Landmarker in VIDEO mode off the UI thread. Receives ImageBitmap frames and
 * returns only landmark arrays: no pixels ever leave this worker or the device (NFR-07).
 * A classic worker is used on purpose: MediaPipe loads its WASM glue with importScripts(), which module
 * workers (and therefore some Safari versions) do not support.
 */
/* global importScripts */
self.module = { exports: {} };
self.exports = self.module.exports;
importScripts("./mediapipe/vision_bundle.js");
const { FilesetResolver, PoseLandmarker } = self.module.exports;

let landmarker = null;
let busy = false;

async function create(model, delegate) {
  const fileset = await FilesetResolver.forVisionTasks(new URL("./mediapipe/wasm", self.location.href).href);
  return PoseLandmarker.createFromOptions(fileset, {
    baseOptions: { modelAssetPath: new URL(`./models/pose_landmarker_${model}.task`, self.location.href).href, delegate },
    runningMode: "VIDEO",
    numPoses: 1,
    minPoseDetectionConfidence: 0.5,
    minPosePresenceConfidence: 0.5,
    minTrackingConfidence: 0.5,
  });
}

async function init(model) {
  if (landmarker) {
    landmarker.close();
    landmarker = null;
  }
  try {
    landmarker = await create(model, "GPU");
    self.postMessage({ type: "ready", model, delegate: "GPU" });
  } catch (gpuErr) {
    // no WebGL in workers on some devices: fall back to the CPU (XNNPACK) delegate
    landmarker = await create(model, "CPU");
    self.postMessage({ type: "ready", model, delegate: "CPU", note: String(gpuErr) });
  }
}

self.onmessage = async (e) => {
  const msg = e.data;
  try {
    if (msg.type === "init") {
      await init(msg.model || "lite");
      return;
    }
    if (msg.type === "frame") {
      if (!landmarker || busy) {
        msg.bitmap.close();
        self.postMessage({ type: "skipped", timestamp: msg.timestamp });
        return;
      }
      busy = true;
      const t0 = performance.now();
      const res = landmarker.detectForVideo(msg.bitmap, msg.timestamp);
      msg.bitmap.close();
      busy = false;

        self.postMessage({ type: "skipped", timestamp: msg.timestamp });
        return;
      }
      busy = true;
      const t0 = performance.now();
      const res = landmarker.detectForVideo(msg.bitmap, msg.timestamp);
      msg.bitmap.close();
      busy = false;
      self.postMessage({
        type: "result",
        timestamp: msg.timestamp,
        inferenceMs: performance.now() - t0,
        landmarks: res.landmarks && res.landmarks[0] ? res.landmarks[0] : null,
        worldLandmarks: res.worldLandmarks && res.worldLandmarks[0] ? res.worldLandmarks[0] : null,
      });
    }
  } catch (err) {
    busy = false;
    self.postMessage({ type: "error", message: String(err && err.message ? err.message : err) });
  }
};

/* FitVision AI service worker: offline shell + long-lived cache for hashed assets, WASM and models. */
const VERSION = "fv-v2";
const STATIC = `${VERSION}-static`;
const SHELL = ["/", "/index.html", "/manifest.webmanifest", "/pose-worker.js"];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(STATIC).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => !k.startsWith(VERSION)).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== "GET" || url.origin !== self.location.origin || url.pathname.startsWith("/api/")) return;
  const cacheFirst = /^\/(assets|mediapipe|models|icons)\//.test(url.pathname);
  if (cacheFirst) {
    e.respondWith(
      caches.match(e.request).then(
        (hit) =>
          hit ||
          fetch(e.request).then((res) => {
            if (res.ok) caches.open(STATIC).then((c) => c.put(e.request, res.clone()));
            return res;
          }),
      ),
    );
    return;
  }
  if (e.request.mode === "navigate") {
    // Open instantly: if the server is slow (a free cloud server waking up), serve the cached app shell after 1.2 s
    // and keep the fresh copy for next time. The app itself then shows "waking the server" while the API wakes.
    const network = fetch(e.request).then((res) => {
      if (res.ok) caches.open(STATIC).then((c) => c.put("/index.html", res.clone()));
      return res;
    });
    const cached = new Promise((resolve) => setTimeout(() => caches.match("/index.html").then(resolve), 1200));
    e.respondWith(
      Promise.race([network, cached])
        .then((r) => r || network)
        .catch(() => caches.match("/index.html")),
    );
  }
});

// Self-hosts MediaPipe (6.3.2): copies the CommonJS bundle and the WASM files out of node_modules
// and downloads the BlazePose models once, so the app never loads them from third-party servers.
import { copyFileSync, cpSync, existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const pkg = join(root, "node_modules", "@mediapipe", "tasks-vision");
const out = join(root, "public", "mediapipe");
const models = join(root, "public", "models");
mkdirSync(out, { recursive: true });
mkdirSync(models, { recursive: true });

if (!existsSync(pkg)) {
  console.error("@mediapipe/tasks-vision is missing – run npm install first");
  process.exit(1);
}
const bundle = ["vision_bundle.cjs", "vision_bundle.js"].find((f) => existsSync(join(pkg, f)));
if (!bundle) {
  console.error("vision bundle not found in @mediapipe/tasks-vision");
  process.exit(1);
}
