const PRAISE_EN = ["Great!", "Perfect rep", "Nice", "Exactly like that", "Clean form", "Strong!", "Spot on"];
const T = {
  he: { done: "סט הושלם! 🎉", last: "אחרונה!", three: "עוד 3!", half: "חצי דרך 💪", streak: (n: number) => `${n} מושלמות ברצף 🔥` },
