const prefix = (lang: CueLang) => (lang === "en" ? "en" : lang === "he" ? "he" : lang);
export function voiceFor(lang: CueLang): SpeechSynthesisVoice | undefined {
  const all = loadVoices();
  const p = prefix(lang);
