    onMutate: async (text) => {
      await qc.cancelQueries({ queryKey: key });
      const prev = qc.getQueryData<Report>(key);
      if (prev)
        qc.setQueryData<Report>(key, {
          ...prev,
          status: prev.status === "Draft" ? "Reviewed" : prev.status,
