      return { prev };
    },
    onError: (e, _t, ctx) => {
      if (ctx?.prev) qc.setQueryData(key, ctx.prev);
      setMsg((e as Error).message);
    },
    onSettled: () => qc.invalidateQueries({ queryKey: key }),
  });

