      setMsg(`הקובץ הופק תוך ${((performance.now() - t0) / 1000).toFixed(1)} שניות`);
    } catch (e: any) {
      setMsg(e.message);
    } finally {
      setBusy(null);
    }
  }

    setMsg(`הקובץ הופק תוך ${((performance.now() - t0) / 1000).toFixed(1)} שניות`);
  } catch (e: any) {
    setMsg(e.message);
  } finally {
    setBusy(null);
  }
}

