  setBusy("send");
  setMsg(null);
  const prev = qc.getQueryData<Report>(key);
  if (prev) qc.setQueryData<Report>(key, { ...prev, status: "Sent" });
  try {
    const job = await api<Job>(`/reports/${id}/send`, { method: "POST", json: { channel, file_format: "PDF" } });
